import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static int add_mod(int a, int b) {
        a += b;
        if (a >= MOD) a -= MOD;
        return a;
    }

    static int multiply_mod(int a, int b) {
        long res = 1L * a * b;
        if (res >= MOD) res %= MOD;
        return (int) res;
    }

    static int subtract_mod(int a, int b) {
        a -= b;
        if (a < 0) a += MOD;
        return a;
    }

    static int power_mod(int base, int exp) {
        int result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = multiply_mod(result, base);
            base = multiply_mod(base, base);
            exp >>= 1;
        }
        return result;
    }

    static int low_bit(int x) {
        return x & (-x);
    }

    static int n;
    static int[][] a = new int[10][10];
    static int[][] q = new int[10][1 << 10];
    static int[][] ch = new int[70010][1 << 10];
    static int[] dp = new int[70010];
    static Map<BitSet, Integer> id = new HashMap<>();
    static int idcnt = 0;

    static int dfs(BitSet s) {
        if (id.containsKey(s)) return id.get(s);
        id.put(s, ++idcnt);
        for (int i = 0; i < (1 << n); i++) {
            BitSet tmp = (BitSet) s.clone();
            for (int j = 0; j < (1 << n); j++) {
                if (!tmp.get(j)) {
                    int x = i & j;
                    while (x != 0) {
                        int t = low_bit(x);
                        if (s.get(j ^ (int)(Math.log(t) / Math.log(2)))) {
                            tmp.set(j);
                            break;
                        }
                        x -= t;
                    }
                }
            }
            ch[id.get(s)][i] = dfs(tmp);
        }
        return id.get(s);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        dfs(new BitSet()); // Initialize with empty set
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < n; j++) {
                a[i][j] = multiply_mod(Integer.parseInt(parts[j]), power_mod(100, MOD - 2));
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                q[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) == 1) {
                        q[i][j] = multiply_mod(q[i][j], a[i][k]);
                    } else {
                        q[i][j] = multiply_mod(q[i][j], subtract_mod(1, a[i][k]));
                    }
                }
            }
        }
        int[] dpPrev = new int[idcnt + 1];
        int[] dpCurr = new int[idcnt + 1];
        Arrays.fill(dpPrev, 0);
        Arrays.fill(dpCurr, 0);
        dpPrev[1] = 1; // Corresponds to dp[0][1] in C++
        for (int i = 1; i <= n; i++) {
            Arrays.fill(dpCurr, 0);
            for (int j = 1; j <= idcnt; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int to = ch[j][k];
                    dpCurr[to] = add_mod(dpCurr[to], multiply_mod(dpPrev[j], q[i - 1][k]));
                }
            }
            int[] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
        }
        BitSet bt = new BitSet(n);
        for (int i = 0; i < (1 << n); i++) {
            bt.set(i);
        }
        int result = dpPrev[id.get(bt)];
        System.out.println(result);
    }
}
